param([string]$Implementation=$env:NETWORK_API_IMPL);$R=Split-Path $PSScriptRoot -Parent;if([string]::IsNullOrWhiteSpace($Implementation)){$Implementation='python'};switch($Implementation){python{python "$R/python/app.py"}node{node "$R/node/app.js"}typescript{npx --yes tsx "$R/typescript/app.ts"}go{go run "$R/go/main.go"}rust{cargo run --manifest-path "$R/rust/Cargo.toml"}java{New-Item -ItemType Directory -Force "$R/java/out"|Out-Null;javac "$R/java/Main.java" -d "$R/java/out";java -cp "$R/java/out" Main}csharp{dotnet run --project "$R/csharp"}cpp{c++ -std=c++17 "$R/cpp/main.cpp" -o "$R/cpp/network-api.exe";& "$R/cpp/network-api.exe"}dart{dart run "$R/dart/bin/main.dart"}kotlin{kotlinc "$R/kotlin/Main.kt" -include-runtime -d "$R/kotlin/network-api.jar";java -jar "$R/kotlin/network-api.jar"}swift{swift "$R/swift/main.swift"}php{php "$R/php/main.php"}ruby{ruby "$R/ruby/main.rb"}default{throw "Unknown NETWORK_API_IMPL: $Implementation"}}
